310	// DeleteNote implements the delete_note tool
311	func (h *Handler) DeleteNote(ctx context.Context, req *mcp.CallToolRequest, input note.DeleteNoteInput) (*mcp.CallToolResult, note.DeleteNoteOutput, error) {
312		if !strings.HasSuffix(strings.ToLower(input.Path), ".md") {
313			return nil, note.DeleteNoteOutput{}, fmt.Errorf("can only delete .md files")
314		}
315	
316		allowed, err := h.vault.IsPathAllowed(input.Path)
317		if err != nil {
318			return nil, note.DeleteNoteOutput{}, fmt.Errorf("path validation error: %w", err)
319		}
320		if !allowed {
321			return nil, note.DeleteNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
322		}
323	
324		info, err := os.Stat(input.Path)
325		if os.IsNotExist(err) {
326			return nil, note.DeleteNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
327		}
328		if err != nil {
329			return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to stat file: %w", err)
330		}
331		if info.IsDir() {
332			return nil, note.DeleteNoteOutput{}, fmt.Errorf("cannot delete directories")
333		}
334	
335		if err := os.Remove(input.Path); err != nil {
336			return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to delete file: %w", err)
337		}
338	
339		output := note.DeleteNoteOutput(input)
340		result := &mcp.CallToolResult{
341			Content: []mcp.Content{
342				&mcp.TextContent{Text: fmt.Sprintf("Deleted note: %s", input.Path)},
343			},
344		}
345		return result, output, nil
346	}
