348	// SearchContent implements the search_content tool
349	func (h *Handler) SearchContent(ctx context.Context, req *mcp.CallToolRequest, input note.SearchContentInput) (*mcp.CallToolResult, note.SearchContentOutput, error) {
350		query := input.Query
351	
352		// Use case-insensitive literal matching via regexp.QuoteMeta to prevent
353		// regex injection from user-provided queries
354		re := regexp.MustCompile("(?i)" + regexp.QuoteMeta(query))
355	
356		var results []note.ContentMatch
357	
358		err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
359			if ctx.Err() != nil {
360				return ctx.Err()
361			}
362	
363			if err != nil {
364				h.logger.Debug("skipping path", "path", path, "error", err)
365				return nil
366			}
367	
368			if info.IsDir() {
369				allowed, checkErr := h.vault.IsPathAllowed(path)
370				if checkErr != nil || !allowed {
371					return filepath.SkipDir
372				}
373				return nil
374			}
375	
376			if !strings.HasSuffix(strings.ToLower(path), ".md") {
377				return nil
378			}
379	
380			allowed, checkErr := h.vault.IsPathAllowed(path)
381			if checkErr != nil || !allowed {
382				return nil
383			}
384	
385			data, err := os.ReadFile(path)
386			if err != nil {
387				h.logger.Debug("skipping unreadable file", "path", path, "error", err)
388				return nil
389			}
390	
391			lines := strings.Split(string(data), "\n")
392			for lineNum, line := range lines {
393	
394				if re.MatchString(line) {
395					results = append(results, note.ContentMatch{
396						Path:    path,
397						Snippet: line,
398						Line:    lineNum + 1,
399					})
400					if len(results) >= vault.MaxSearchResults {
401						return filepath.SkipAll
402					}
403				}
404			}
405	
406			return nil
407		})
408	
409		if err != nil {
410			return nil, note.SearchContentOutput{}, fmt.Errorf("failed to search content: %w", err)
411		}
412	
413		output := note.SearchContentOutput{Results: results}
414	
415		textContent := fmt.Sprintf("Found %d matching lines", len(results))
416		if len(results) > 0 {
417			var lines []string
418			for _, m := range results {
419				lines = append(lines, fmt.Sprintf("%s:%d: %s", m.Path, m.Line, m.Snippet))
420			}
421			textContent += ":\n" + strings.Join(lines, "\n")
422		}
423	
424		result := &mcp.CallToolResult{
425			Content: []mcp.Content{
426				&mcp.TextContent{Text: textContent},
427			},
428		}
429		return result, output, nil
430	}
